		// Leap year bug tests
		// 2000 is a leap year (divisible by 400)
		{name: "Leap Year 2000 (correct)", income: 30000, year: 2000, expectedTax: 2000 + (10000 * 0.15) - 500, expectError: false}, // Expecting bug: -500 deduction applied
