		{name: "Leap Year 2004 (correct)", income: 30000, year: 2004, expectedTax: 2000 + (10000 * 0.15) - 500, expectError: false}, // Expecting bug: -500 deduction applied
		// 1900 is NOT a leap year (divisible by 100 but not by 400)
		{name: "Non-Leap Year 1900 (incorrectly identified by isLeapYear)", income: 30000, year: 1900, expectedTax: 2000 + (10000 * 0.15) - 500, expectError: false}, // Expecting bug: -500 deduction applied due to isLeapYear bug
