		{name: "Non-Leap Year 2100 (incorrectly identified by isLeapYear)", income: 30000, year: 2100, expectedTax: 2000 + (10000 * 0.15) - 500, expectError: false}, // Expecting bug: -500 deduction applied due to isLeapYear bug
		// 2023 is a non-leap year
		{name: "Non-Leap Year 2023", income: 30000, year: 2023, expectedTax: 2000 + (10000 * 0.15), expectError: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tax, err := CalculateTax(tt.income, tt.year)

			if tt.expectError {
				if err == nil {
					t.Errorf("expected an error for income %f, got nil", tt.income)
				}
			} else {
				if err != nil {
					t.Errorf("did not expect an error for income %f, got %v", tt.income, err)
				}
				if tax != tt.expectedTax {
					t.Errorf("For income %f, year %d, expected tax %.2f, got %.2f", tt.income, tt.year, tt.expectedTax, tax)
				}
			}
		})
	}
}

